            pstmt.setString(1, orderId);
            ResultSet rs = pstmt.executeQuery();
            if (rs.next()) {
                String existing = rs.getString("payment_transaction_id");
                return existing != null && existing.equals(transactionId);
            }
            return false;
        }
    }
