        item.quantity = 1;
        req.items = new ArrayList<>();
        req.items.add(item);

        req.zipCode = "01310100";
        req.region = "SOUTHEAST";
        req.shippingMethod = "STORE_PICKUP";
        req.paymentMethod = "PIX";
        req.clubTier = "BRONZE";

        CheckoutService.ValidationError error = CheckoutService.validateCheckoutRequest(req);
        assert error == null : "Validation should pass";

        OrderSummary summary = CheckoutService.calculateSummary(req);
        assertNotNull("Summary should not be null", summary);
    }
}

