        }

        if (Enums.ClubTier.valueOf(req.clubTier) == Enums.ClubTier.GOLD &&
            !req.shippingMethod.equals("COURIER") &&
            !req.shippingMethod.equals("STORE_PICKUP")) {
            shippingCost = 0;
        }

