        }

        if (coupon.equals("MINUS50")) {
            if (subtotal < 300) {
                return 0;
            }
            return 50.0;
        }

        if (coupon.equals("FREESHIPPING")) {
            if (req.shippingMethod.equals("STORE_PICKUP")) {
                return 0;
            }
            ShippingInfo shipping = calculateShipping(req);
            if (shipping == null) {
                return 0;
            }
