        public String code;
        public int httpStatus;

        public ValidationError(String code, int httpStatus) {
            this.code = code;
            this.httpStatus = httpStatus;
        }
    }

    private static class ShippingInfo {
        double cost;
        int days;

        ShippingInfo(double cost, int days) {
            this.cost = cost;
            this.days = days;
        }
    }

    private static class TranslogResponse {
        int priceCents;
        int etaHours;
        String error;
    }
